f = open('26.txt')
n = int(f.readline())
busy = sorted(tuple(map(int, f.readline().split())) for _ in range(n))
best = None
for (r1, s1), (r2, s2) in zip(busy, busy[1:]):
    if r1 == r2 and s2 - s1 == 3:
        if best is None or r1 > best[0] or (r1 == best[0] and s1 + 1 < best[1]):
            best = (r1, s1 + 1)
print(*best)

f = open('26.txt')
n = int(f.readline())
cnt = {}
for _ in range(n):
    x = int(f.readline())
    cnt[x] = cnt.get(x, 0) + 1
k = 0
for x, c in cnt.items():
    y = 10000 - x
    if x < y:
        k += c * cnt.get(y, 0)
    elif x == y:
        k += c * (c - 1) // 2
print(k)
